function reportFilter(req:Request):ReportFilter{const q=req.query,base=summaryFilter(req),report=Number(q.report??1);if(!Number.isSafeInteger(report)||report<1||report>20)invalid('Relatório inválido.');let {from,to}=base;if(report===18){const month=text(q.month??from.slice(0,7),7);if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))invalid('Mês inválido.');from=month+'-01';const next=new Date(from+'T00:00:00Z');next.setUTCMonth(next.getUTCMonth()+1);next.setUTCDate(0);to=next.toISOString().slice(0,10);}if(report===19){const year=Number(q.year??from.slice(0,4));if(!Number.isSafeInteger(year)||year<1900||year>2100)invalid('Ano inválido.');from=year+'-01-01';to=year+'-12-31';}const selection=(key:string):Selection=>{const mode=String(q[key+'Mode']??'any');if(!['any','filled','values'].includes(mode))invalid('Modo de filtro inválido.');const raw=String(q[key+'Ids']??'');const ids=raw?raw.split(',').map(v=>text(v,160)):[];if(ids.length>100||mode==='values'&&!ids.length)invalid('Selecione valores do filtro.');return {mode:mode as Selection['mode'],ids};};const bool=(k:string)=>{if(q[k]!==undefined&&!['true','false'].includes(String(q[k])))invalid('Filtro booleano inválido.');return q[k]!=='false';};const basis=String(q.basis??'competence');if(!['payment','competence'].includes(basis))invalid('Regime inválido.');return {...base,from,to,report,basis:basis as ReportFilter['basis'],includePaid:bool('includePaid'),includeUnpaid:bool('includeUnpaid'),category:selection('category'),contact:selection('contact'),tag:selection('tag'),costCenter:selection('costCenter'),method:selection('method'),plan:selection('plan'),project:selection('project'),contract:selection('contract')};}
router.get('/reports',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');const f=reportFilter(req),format=String(req.query.format??'json');if(!['json','csv','pdf','xlsx'].includes(format))invalid('Formato inválido.');if(format!=='json')await access(u,company,'export');const result=await consistentRead(u,company,async c=>{await access(u,company,'balances',c);if(format!=='json')await access(u,company,'export',c);const allowed=new Set<string>();for(const b of Object.keys(buckets))if(await checkAccess(u,'scope-company:'+company,'finance',b+'.read',c))allowed.add(b);if([14,15,20].includes(f.report)&&allowed.size!==Object.keys(buckets).length)throw new HttpError(403,'Extratos e saldos completos exigem leitura de todos os tipos financeiros.');const aa=await accounts(company,c),cc=await categories(company,c),dims=await rows<{id:string;name:string}>('SELECT id,name FROM finance_dimensions WHERE company_id=?',[company],c),parties=await rows<{id:string;name:string}>('SELECT DISTINCT p.id,p.name FROM business_parties p WHERE EXISTS(SELECT 1 FROM customer_parties l WHERE l.party_id=p.id AND l.company_id=?) OR EXISTS(SELECT 1 FROM supplier_company_drafts s WHERE s.party_id=p.id AND s.company_id=?)',[company,company],c),labels=Object.fromEntries([...aa,...cc,...dims,...parties].map(v=>[v.id,v.name]));const input={accounts:aa,categories:cc,titles:(await titles(company,c)).filter(t=>allowed.has(t.payload.bucket)),settlements:await settlements(company,c),movements:await movements(company,c),labels};const report=buildReport(input,f);const [companyRow]=await rows<{name:string}>('SELECT name FROM companies WHERE id=?',[company],c);let comparison=null;if([18,19].includes(f.report)){const prev=new Date(f.from+'T00:00:00Z');if(f.report===18)prev.setUTCMonth(prev.getUTCMonth()-1);else prev.setUTCFullYear(prev.getUTCFullYear()-1);const end=new Date(f.from+'T00:00:00Z');end.setUTCDate(0);const prior=buildReport(input,{...f,from:prev.toISOString().slice(0,10),to:end.toISOString().slice(0,10)});const variation=(value:string,old:string)=>cents(old)===0n?null:Number((cents(value)-cents(old))*10000n/(cents(old)<0n?-cents(old):cents(old)))/100;comparison={from:prior.filter.from,to:prior.filter.to,income:prior.totalIncome,expense:prior.totalExpense,net:prior.net,incomeVariation:variation(report.totalIncome,prior.totalIncome),expenseVariation:variation(report.totalExpense,prior.totalExpense)};}return {...report,comparison,companyId:company,companyName:companyRow.name,emittedAt:new Date().toISOString()};});await readAudit(u,company,'report.'+f.report+'.'+format);if(format==='csv'||format==='xlsx'){const lines=[['Empresa',result.companyName,'Moeda',f.currency,'Início',result.filter.from,'Fim',result.filter.to],['Grupo','Recebimentos','Despesas','Resultado','IDs de títulos'],...result.rows.map(r=>[r.label,r.income,r.expense,r.net,r.titleIds.join(' ')]),['Total de fatos únicos',result.totalIncome,result.totalExpense,result.net],...result.warnings.map(w=>['Aviso',w])];if(format==='xlsx'){res.type('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet').attachment('relatorio-financeiro.xlsx').send(exportXlsx(lines));return;}res.type('text/csv; charset=utf-8').attachment('relatorio-financeiro.csv').send('\uFEFF'+lines.map(r=>r.map(csvCell).join(';')).join('\r\n'));}else if(format==='pdf')res.type('application/pdf').attachment('relatorio-financeiro.pdf').send(await generatePDF({title:result.companyName+' — '+result.name+' — '+f.currency+' — '+result.filter.from+' a '+result.filter.to,filename:'relatorio-financeiro.pdf',columns:[{header:'Grupo',dataKey:'label'},{header:'Receitas',dataKey:'income'},{header:'Despesas',dataKey:'expense'},{header:'Resultado',dataKey:'net'}],data:[...result.rows,...result.warnings.map(label=>({label,income:'',expense:'',net:''}))]}));else res.json(result);});

async function budget(id:unknown,company:string,c:PoolConnection|typeof pool=pool){const [b]=await rows<Budget>('SELECT id,company_id companyId,name,currency,year,status,revision,version,series_id seriesId,payload FROM finance_budgets WHERE id=? AND company_id=?',[uuid(id),company],c);if(!b)throw new HttpError(404,'Orçamento fora da empresa.');return {...b,payload:decode(b.payload)} as Budget;}
async function allBuckets(u:Principal,company:string,c:PoolConnection|typeof pool=pool){for(const b of Object.keys(buckets))await bucketAccess(u,company,b as Bucket,'read',c);}
async function budgetInput(v:unknown,company:string,c:PoolConnection){const d=obj(v);fields(d,['name','currency','year','lines','assumptions']);const year=Number(d.year);if(!Number.isSafeInteger(year)||year<1900||year>2100)invalid('Ano inválido.');if(!Array.isArray(d.lines)||d.lines.length>1200)invalid('Linhas inválidas.');const cs=await categories(company,c),keys=new Set<string>(),lines:BudgetLine[]=[];for(const rawLine of d.lines){const l=obj(rawLine);fields(l,['categoryId','month','amount']);const categoryId=uuid(l.categoryId),month=text(l.month,7),value=decimal(l.amount);if(!new RegExp('^'+year+'-(0[1-9]|1[0-2])$').test(month)||!cs.some(c=>c.id===categoryId&&c.active&&!c.nature.startsWith('advance_'))||keys.has(categoryId+month))invalid('Categoria/mês repetido, fora da empresa ou inativo.');keys.add(categoryId+month);lines.push({categoryId,month,amount:value});}return {name:text(d.name,160),currency:currency(d.currency),year,payload:{lines,assumptions:text(d.assumptions,6000)}};}
router.get('/budgets',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');await allBuckets(u,company);res.json(await consistentRead(u,company,async c=>{await allBuckets(u,company,c);const list=await rows<{id:string}>('SELECT id FROM finance_budgets WHERE company_id=? ORDER BY year DESC,series_id,version DESC',[company],c);return Promise.all(list.map(async r=>{const b=await budget(r.id,company,c);return {...b,comparison:compareBudget(b,await titles(company,c),await settlements(company,c),await categories(company,c),day(req.query.asOf??today())),asOf:day(req.query.asOf??today()),unclassifiedTitleIds:(await titles(company,c)).filter(t=>t.status==='approved'&&t.payload.currency===b.currency&&t.payload.competenceDate.startsWith(b.year+'-')&&!t.payload.categoryId).map(t=>t.id)};}));}));await readAudit(u,company,'budget.read');});
router.get('/budgets/proposal',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');await allBuckets(u,company);const year=Number(req.query.year),cur=currency(req.query.currency);if(!Number.isSafeInteger(year)||year<1901||year>2100)invalid('Ano inválido.');const lines=await consistentRead(u,company,async c=>{await allBuckets(u,company,c);return budgetProposal(year,cur,await titles(company,c));});await readAudit(u,company,'budget.proposal');res.json({lines,assumptions:'Proposta determinística: valores aprovados por categoria e mês do ano anterior, sem inflação ou crescimento presumidos. Revisar antes de salvar.',sourceYear:year-1,currency:cur,year,ai:false});});
router.post('/budgets',async(req,res)=>{const company=co(req),u=res.locals.user;res.status(201).json(await write(req,u,company,'governance',async(c,b)=>{fields(b,['companyId','requestId','data','reason']);const d=await budgetInput(b.data,company,c);await openPeriods(company,d.payload.lines.map(l=>l.month+'-01'),c);const id=randomUUID();await c.execute('INSERT INTO finance_budgets(id,company_id,name,currency,year,version,series_id,payload) VALUES (?,?,?,?,?,1,?,?)',[id,company,d.name,d.currency,d.year,id,json(d.payload)]);await history(c,u,company,'budget',id,1,'create',b.reason,null,d);return {id,revision:1,version:1};},async c=>allBuckets(u,company,c)));});
router.put('/budgets/:id',async(req,res)=>{const company=co(req),u=res.locals.user;res.json(await write(req,u,company,'governance',async(c,b)=>{fields(b,['companyId','requestId','revision','data','reason']);const old=await budget(req.params.id,company,c);cas(b.revision,old.revision);if(old.status!=='draft')throw new HttpError(409,'Plano aprovado é imutável; crie nova versão.');const d=await budgetInput(b.data,company,c);if(d.currency!==old.currency||d.year!==old.year)invalid('Moeda/ano imutáveis na série.');await openPeriods(company,[...old.payload.lines,...d.payload.lines].map(l=>l.month+'-01'),c);const revision=old.revision+1;await c.execute('UPDATE finance_budgets SET name=?,payload=?,revision=? WHERE id=? AND company_id=?',[d.name,json(d.payload),revision,old.id,company]);await history(c,u,company,'budget',old.id,revision,'edit',b.reason,old,d);return {id:old.id,revision};},async c=>allBuckets(u,company,c)));});
router.post('/budgets/:id/:action',async(req,res)=>{const company=co(req),u=res.locals.user,action=String(req.params.action);if(!['approve','revise'].includes(action))throw new HttpError(404,'Ação inválida.');res.json(await write(req,u,company,action==='approve'?'approve':'governance',async(c,b)=>{fields(b,['companyId','requestId','revision','reason']);const old=await budget(req.params.id,company,c);cas(b.revision,old.revision);if(old.status!==(action==='approve'?'draft':'approved'))throw new HttpError(409,'Estado incompatível.');await openPeriods(company,old.payload.lines.map(l=>l.month+'-01'),c);if(action==='revise'){if((await rows('SELECT id FROM finance_budgets WHERE series_id=? AND version>?',[old.seriesId,old.version],c)).length)throw new HttpError(409,'Já há versão posterior nesta série.');const id=randomUUID();await c.execute('INSERT INTO finance_budgets(id,company_id,name,currency,year,version,series_id,payload) VALUES (?,?,?,?,?,?,?,?)',[id,company,old.name,old.currency,old.year,old.version+1,old.seriesId,json({...old.payload,sourceId:old.id})]);await history(c,u,company,'budget',id,1,'revise',b.reason,old,{...old,id,version:old.version+1,status:'draft',revision:1});return {id,revision:1,version:old.version+1};}if(!old.payload.lines.length)invalid('Orçamento vazio não pode ser aprovado.');for(const previous of await rows<{id:string}>('SELECT id FROM finance_budgets WHERE series_id=? AND status="approved"',[old.seriesId],c)){const p=await budget(previous.id,company,c);await c.execute('UPDATE finance_budgets SET status="superseded",revision=revision+1 WHERE id=?',[p.id]);await history(c,u,company,'budget',p.id,p.revision+1,'supersede',b.reason,p,{successor:old.id});}await c.execute('UPDATE finance_budgets SET status="approved",revision=revision+1 WHERE id=?',[old.id]);await history(c,u,company,'budget',old.id,old.revision+1,'approve',b.reason,old,{...old,status:'approved',revision:old.revision+1});return {id:old.id,revision:old.revision+1,status:'approved'};},async c=>allBuckets(u,company,c)));});

router.get('/titles/:id/files',async(req,res)=>{const company=co(req),u=res.locals.user,t=await title(req.params.id,company);await bucketAccess(u,company,t.payload.bucket,'read');await access(u,company,'attachments');await readAudit(u,company,'file.list');res.json(await rows('SELECT id,title_id titleId,series_id seriesId,version,file_name fileName,mime_type mimeType,size,sha256,status,revision FROM finance_private_files WHERE company_id=? AND title_id=? ORDER BY series_id,version DESC',[company,t.id]));});
router.post('/titles/:id/files',async(req,res)=>{const company=co(req),u=res.locals.user;res.status(201).json(await write(req,u,company,'attachments',async(c,b)=>{fields(b,['companyId','requestId','fileName','mimeType','contentBase64','previousId','reason']);const t=await title(req.params.id,company,c);await openPeriods(company,[t.payload.competenceDate,t.payload.dueDate],c);const fileName=text(b.fileName,160),mimeType=text(b.mimeType,100);if(!/^[\p{L}\p{N} _.-]+$/u.test(fileName)||fileName.includes('..')||! /\.(pdf|docx|xlsx|png|jpe?g)$/i.test(fileName))invalid('Nome/formato documental inválido.');const max=Number(process.env.FINANCE_ATTACHMENT_MAX_BYTES??2*1024*1024),content=validateFile(fileName,mimeType,b.contentBase64,max);let seriesId:string=randomUUID(),version=1;if(b.previousId){const [old]=await rows<{seriesId:string;version:number;titleId:string;status:string}>('SELECT series_id seriesId,version,title_id titleId,status FROM finance_private_files WHERE id=? AND company_id=?',[uuid(b.previousId),company],c);if(!old||old.titleId!==t.id||old.status!=='active')invalid('Versão anterior fora do título/empresa.');const [latest]=await rows<{version:number}>('SELECT MAX(version) version FROM finance_private_files WHERE series_id=? AND company_id=?',[old.seriesId,company],c);if(latest.version!==old.version)throw new HttpError(409,'Arquivo substituído; recarregue.');seriesId=old.seriesId;version=old.version+1;}const id=randomUUID(),sha256=createHash('sha256').update(content).digest('hex');await c.execute('INSERT INTO finance_private_files(id,company_id,title_id,series_id,version,file_name,mime_type,content,size,sha256,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?)',[id,company,t.id,seriesId,version,fileName,mimeType,content,content.length,sha256,u.id]);await history(c,u,company,'file',id,1,'upload',b.reason,null,{titleId:t.id,seriesId,version,fileName,mimeType,size:content.length,sha256});return {id,seriesId,version,sha256};},async c=>{const t=await title(req.params.id,company,c);await bucketAccess(u,company,t.payload.bucket,'edit',c);}));});
router.get('/files/:id/download',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'attachments');const [f]=await rows<{titleId:string;content:Buffer;fileName:string;mimeType:string;sha256:string;status:string}>('SELECT title_id titleId,content,file_name fileName,mime_type mimeType,sha256,status FROM finance_private_files WHERE id=? AND company_id=?',[uuid(req.params.id),company]);if(!f)throw new HttpError(404,'Arquivo fora da empresa.');const t=await title(f.titleId,company);await bucketAccess(u,company,t.payload.bucket,'read');if(f.status==='archived'&&req.query.historical!=='true')throw new HttpError(410,'Arquivo arquivado; solicite cópia histórica.');if(createHash('sha256').update(f.content).digest('hex')!==f.sha256)throw new HttpError(409,'Integridade documental divergente.');await readAudit(u,company,'file.download:'+uuid(req.params.id));res.type(f.mimeType).attachment(f.fileName).send(f.content);});
router.post('/files/:id/status',async(req,res)=>{const company=co(req),u=res.locals.user;res.json(await write(req,u,company,'attachments',async(c,b)=>{fields(b,['companyId','requestId','revision','status','reason']);const [old]=await rows<{titleId:string;status:string;revision:number}>('SELECT title_id titleId,status,revision FROM finance_private_files WHERE id=? AND company_id=?',[uuid(req.params.id),company],c);if(!old)throw new HttpError(404,'Arquivo fora da empresa.');cas(b.revision,old.revision);if(!['active','archived'].includes(String(b.status)))invalid('Estado documental inválido.');const t=await title(old.titleId,company,c);await openPeriods(company,[t.payload.dueDate,t.payload.competenceDate],c);await c.execute('UPDATE finance_private_files SET status=?,revision=revision+1 WHERE id=?',[String(b.status),uuid(req.params.id)]);await history(c,u,company,'file',uuid(req.params.id),old.revision+1,b.status==='active'?'restore':'archive',b.reason,old,{...old,status:b.status,revision:old.revision+1});return {id:req.params.id,status:b.status,revision:old.revision+1};},async c=>{const [f]=await rows<{titleId:string}>('SELECT title_id titleId FROM finance_private_files WHERE id=? AND company_id=?',[uuid(req.params.id),company],c);if(!f)throw new HttpError(404,'Arquivo fora da empresa.');const t=await title(f.titleId,company,c);await bucketAccess(u,company,t.payload.bucket,'edit',c);}));});
router.get('/titles/:id/receipt',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'export');const t=await title(req.params.id,company),data=await position(u,t),[cr]=await rows<{name:string}>('SELECT name FROM companies WHERE id=?',[company]);const footer=text(req.query.footer??'',1000,true),ss=data.settlements.filter(s=>!s.reversed);if(!ss.length)throw new HttpError(409,'Recibo exige liquidação registrada.');const body=[{field:'Empresa',value:cr.name},{field:'Título / referência',value:t.id+' / '+t.payload.documentNumber},{field:'Descrição',value:t.payload.description},{field:'Moeda',value:t.payload.currency},{field:'Valor liquidado',value:data.paid},{field:'Saldo pendente',value:data.pending},...ss.map(s=>({field:'Liquidação '+s.id,value:s.date+' · '+s.amount+' · '+s.method})),{field:'Observação do recibo',value:footer},{field:'Limite',value:'Comprovante gerencial de fatos registrados. Não constitui nota fiscal nem confirmação bancária externa.'}];await readAudit(u,company,'receipt.export:'+t.id);res.type('application/pdf').attachment('recibo-financeiro.pdf').send(await generatePDF({title:'Recibo gerencial — '+cr.name,filename:'recibo-financeiro.pdf',columns:[{header:'Campo',dataKey:'field'},{header:'Informação',dataKey:'value'}],data:body}));});
router.get('/history',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'governance');await allBuckets(u,company);const offset=Number(req.query.offset??0),limit=Number(req.query.limit??50);if(!Number.isSafeInteger(offset)||offset<0||!Number.isSafeInteger(limit)||limit<1||limit>100)invalid('Paginação inválida.');const events=await rows('SELECT entity_type entityType,entity_id entityId,revision,action,actor_id actorId,reason,created_at createdAt FROM finance_history WHERE company_id=? ORDER BY created_at DESC,id DESC LIMIT '+limit+' OFFSET '+offset,[company]);await readAudit(u,company,'history.read');res.json({events,offset,nextOffset:events.length===limit?offset+limit:null});});

function importFile(b:Record<string,unknown>){return {fileName:text(b.fileName,160),mimeType:text(b.mimeType,100),contentBase64:text(b.contentBase64,3*1024*1024)};}
function namespace(v:unknown){const n=text(v,30);if(!/^[a-z0-9_-]+$/.test(n))invalid('Namespace deve ser estável, com letras minúsculas, números, _ ou -.');return n;}

async function prepareTitles(b:Record<string,unknown>,u:Principal,company:string,c:PoolConnection|typeof pool=pool){const f=importFile(b),ns=namespace(b.namespace);let parsed:ReturnType<typeof parseTitleFile>;try{parsed=parseTitleFile(f.fileName,f.mimeType,f.contentBase64,b.mapping as ImportMapping|undefined);}catch(e){invalid((e as Error).message);}const result=[];for(const row of parsed!.rows){const errors=[...row.errors];let data:TitleData|null=null;try{const {externalId,...rest}=row.data;data=titleInput({...rest,tagIds:[]});await bucketAccess(u,company,data.bucket,'edit',c);if(c!==pool){await validateLinks(u,company,data,c as PoolConnection);await openPeriods(company,[data.dueDate,data.competenceDate],c as PoolConnection);}else {const conn=await pool.getConnection();try{await validateLinks(u,company,data,conn);const closed=await rows('SELECT period FROM finance_periods WHERE company_id=? AND period IN (?,?) AND status="closed"',[company,data.dueDate.slice(0,7),data.competenceDate.slice(0,7)],conn);if(closed.length)errors.push('Competência encerrada.');}finally{conn.release();}}}catch(e){if(e instanceof HttpError&&e.status===403)throw e;errors.push((e as Error).message);}const originKey='import:'+ns+':'+row.data.externalId,[existing]=await rows<{id:string}>('SELECT id FROM finance_titles WHERE company_id=? AND origin_key=?',[company,originKey],c);result.push({...row,data,errors,originKey,existingId:existing?.id??null});}return {...parsed!,rows:result,namespace:ns};}
router.post('/imports/titles/preview',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'edit');const b=obj(req.body);fields(b,['companyId','namespace','fileName','mimeType','contentBase64','mapping']);const preview=await prepareTitles(b,u,company);await readAudit(u,company,'import.titles.preview');res.json({...preview,canCommit:preview.rows.every(r=>r.errors.length===0&&!r.existingId),totals:{income:amount(preview.rows.filter(r=>!r.errors.length&&r.data?.bucket==='income').reduce((n,r)=>n+cents(r.data!.amount),0n)),expense:amount(preview.rows.filter(r=>!r.errors.length&&r.data?.bucket!=='income').reduce((n,r)=>n+cents(r.data!.amount),0n))}});});
router.post('/imports/titles/commit',async(req,res)=>{const company=co(req),u=res.locals.user;res.status(201).json(await write(req,u,company,'edit',async(c,b)=>{fields(b,['companyId','requestId','reason','namespace','fileName','mimeType','contentBase64','expectedSha256','mapping']);const parsed=await prepareTitles(b,u,company,c);if(parsed.sha256!==text(b.expectedSha256,64))throw new HttpError(409,'Arquivo mudou após prévia.');if(parsed.rows.some(r=>r.errors.length||r.existingId))throw new HttpError(409,'Linhas inválidas/duplicadas; nada importado. Revise a prévia.');const id=randomUUID(),income=amount(parsed.rows.filter(r=>r.data!.bucket==='income').reduce((n,r)=>n+cents(r.data!.amount),0n)),expense=amount(parsed.rows.filter(r=>r.data!.bucket!=='income').reduce((n,r)=>n+cents(r.data!.amount),0n)),ids:string[]=[];for(const row of parsed.rows){const tid=randomUUID();ids.push(tid);await c.execute('INSERT INTO finance_titles(id,company_id,payload,origin_key) VALUES (?,?,?,?)',[tid,company,json({...row.data,importProvenance:{batchId:id,namespace:parsed.namespace,externalId:row.data?row.originKey.split(':').slice(2).join(':'):'',sha256:parsed.sha256,line:row.line}}),row.originKey]);await history(c,u,company,'title',tid,1,'import_draft',b.reason,null,{payload:row.data,batchId:id,originKey:row.originKey});}await c.execute('INSERT INTO finance_import_batches VALUES (?,?,?,?,?,?,?,?,?,?)',[id,company,'titles',parsed.namespace,parsed.sha256,ids.length,income,expense,json({ids,mapping:b.mapping??null}),u.id]);await history(c,u,company,'import',id,1,'commit',b.reason,null,{namespace:parsed.namespace,sha256:parsed.sha256,count:ids.length,income,expense,ids});return {id,ids,count:ids.length,income,expense,automaticallySettled:false};},async(c,b)=>{await prepareTitles(b,u,company,c);}));});
async function bankInput(b:Record<string,unknown>,company:string,c:PoolConnection|typeof pool=pool){const account=(await accounts(company,c)).find(a=>a.id===uuid(b.accountId));if(!account||!account.active)invalid('Conta inválida.');let parsed:ReturnType<typeof parseOfx>;try{parsed=parseOfx(text(b.contentBase64,3*1024*1024));}catch(e){invalid((e as Error).message);}if(parsed!.currency!==account!.currency||parsed!.accountRef!==text(b.confirmAccountRef,160))invalid('Moeda ou referência bancária não confirmada.');const rowsWithState=[];for(const row of parsed!.rows){const [old]=await rows<{id:string;amount:string;date:string}>('SELECT id,amount,DATE_FORMAT(effective_date,"%Y-%m-%d") date FROM finance_bank_entries WHERE account_id=? AND fit_id=?',[account!.id,row.fitId],c);rowsWithState.push({...row,existingId:old?.id??null,conflict:!!old&&(old.amount!==row.amount||old.date!==row.date),invalidDate:row.date<account!.openingDate||row.date>today()});}return {...parsed!,account:account!,rows:rowsWithState};}
router.post('/imports/ofx/preview',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');await access(u,company,'settle');await allBuckets(u,company);const b=obj(req.body);fields(b,['companyId','accountId','confirmAccountRef','contentBase64']);const parsed=await bankInput(b,company);await readAudit(u,company,'import.ofx.preview');res.json({...parsed,account:undefined,canCommit:parsed.rows.every(r=>!r.conflict&&!r.invalidDate),createsFinancialFacts:false});});
router.post('/imports/ofx/commit',async(req,res)=>{const company=co(req),u=res.locals.user;res.status(201).json(await write(req,u,company,'settle',async(c,b)=>{fields(b,['companyId','requestId','reason','accountId','confirmAccountRef','contentBase64','expectedSha256']);const parsed=await bankInput(b,company,c);if(parsed.sha256!==text(b.expectedSha256,64)||parsed.rows.some(r=>r.conflict||r.invalidDate))throw new HttpError(409,'Arquivo/origem divergiu; nada importado.');await openPeriods(company,parsed.rows.map(r=>r.date),c);const [existingBatch]=await rows<{id:string}>('SELECT id FROM finance_import_batches WHERE company_id=? AND kind="ofx" AND namespace=? AND sha256=?',[company,parsed.account.id.slice(0,30),parsed.sha256],c);if(existingBatch)return {id:existingBatch.id,imported:0,alreadyImported:true};const id=randomUUID(),fresh=parsed.rows.filter(r=>!r.existingId),income=amount(fresh.filter(r=>cents(r.amount)>0n).reduce((n,r)=>n+cents(r.amount),0n)),expense=amount(fresh.filter(r=>cents(r.amount)<0n).reduce((n,r)=>n-cents(r.amount),0n));await c.execute('INSERT INTO finance_import_batches VALUES (?,?,?,?,?,?,?,?,?,?)',[id,company,'ofx',parsed.account.id.slice(0,30),parsed.sha256,fresh.length,income,expense,json({bankAccountRef:parsed.accountRef}),u.id]);for(const row of fresh)await c.execute('INSERT INTO finance_bank_entries(id,company_id,account_id,batch_id,fit_id,effective_date,amount,description) VALUES (?,?,?,?,?,?,?,?)',[randomUUID(),company,parsed.account.id,id,row.fitId,row.date,row.amount,row.description]);await history(c,u,company,'import',id,1,'ofx_commit',b.reason,null,{sha256:parsed.sha256,imported:fresh.length,duplicates:parsed.rows.length-fresh.length,income,expense});return {id,imported:fresh.length,duplicates:parsed.rows.length-fresh.length,createsFinancialFacts:false};},async c=>{await access(u,company,'balances',c);await allBuckets(u,company,c);}));});
router.get('/imports',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');await allBuckets(u,company);res.json(await rows('SELECT id,kind,namespace,sha256,row_count rowCount,total_income income,total_expense expense,payload FROM finance_import_batches WHERE company_id=? ORDER BY id',[company]));await readAudit(u,company,'import.list');});
router.get('/bank-entries',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');await allBuckets(u,company);res.json(await rows('SELECT b.id,b.account_id accountId,b.fit_id fitId,DATE_FORMAT(b.effective_date,"%Y-%m-%d") date,b.amount,b.description,b.settlement_id settlementId,b.revision,CASE WHEN s.reversed=1 THEN "invalidated_reversal" WHEN s.id IS NOT NULL THEN "matched" ELSE "unmatched" END reconciliationStatus FROM finance_bank_entries b LEFT JOIN finance_settlements s ON s.id=b.settlement_id WHERE b.company_id=? ORDER BY b.effective_date,b.id',[company]));await readAudit(u,company,'bank.read');});
router.post('/bank-entries/:id/:action',async(req,res)=>{const company=co(req),u=res.locals.user,action=String(req.params.action);if(!['match','unmatch'].includes(action))throw new HttpError(404,'Ação inválida.');res.json(await write(req,u,company,'settle',async(c,b)=>{fields(b,['companyId','requestId','reason','revision','settlementId']);const [old]=await rows<{id:string;accountId:string;date:string;amount:string;settlementId:string|null;revision:number}>('SELECT id,account_id accountId,DATE_FORMAT(effective_date,"%Y-%m-%d") date,amount,settlement_id settlementId,revision FROM finance_bank_entries WHERE id=? AND company_id=?',[uuid(req.params.id),company],c);if(!old)throw new HttpError(404,'Movimento fora da empresa.');cas(b.revision,old.revision);await openPeriods(company,[old.date],c);let settlementId:string|null=null;if(action==='match'){if(old.settlementId)throw new HttpError(409,'Movimento já conciliado.');settlementId=uuid(b.settlementId);const [s]=await rows<Settlement>('SELECT id,title_id titleId,account_id accountId,amount,DATE_FORMAT(payment_date,"%Y-%m-%d") date,method,notes,reversed,settlement_kind kind,advance_id advanceId,funding_settlement_id fundingSettlementId FROM finance_settlements WHERE id=? AND company_id=?',[settlementId,company],c);if(!s||s.kind==='advance_offset'||s.reversed||s.accountId!==old.accountId||s.date!==old.date)invalid('Liquidação incompatível com conta/data ou estornada.');const t=await title(s.titleId,company,c);await bucketAccess(u,company,t.payload.bucket,'settle',c);if((t.payload.bucket==='income'?s.amount:amount(-cents(s.amount)))!==old.amount)invalid('Valor da liquidação diverge do extrato.');}else if(!old.settlementId)throw new HttpError(409,'Movimento não conciliado.');await c.execute('UPDATE finance_bank_entries SET settlement_id=?,revision=revision+1 WHERE id=?',[settlementId,old.id]);await history(c,u,company,'bank_entry',old.id,old.revision+1,action,b.reason,old,{settlementId});return {id:old.id,revision:old.revision+1,settlementId,createdFinancialFact:false};},async c=>{await access(u,company,'balances',c);await allBuckets(u,company,c);}));});

router.put('/series/:id/drafts',async(req,res)=>{
 const company=co(req),u=res.locals.user,seriesId=uuid(req.params.id);
 res.json(await write(req,u,company,'edit',async(c,b)=>{
  fields(b,['companyId','requestId','reason','anchorId','scope','revisions','patch']);
  const anchor=await title(b.anchorId,company,c);
  if(anchor.seriesId!==seriesId||anchor.status!=='draft'||!anchor.payload.schedule)throw new HttpError(409,'Selecione um rascunho da série.');
  if(!['future','all'].includes(String(b.scope)))invalid('Selecione os próximos ou todos os rascunhos.');
  const patch=obj(b.patch);fields(patch,['description','notes','categoryId','accountId']);
  if(!Object.keys(patch).length)invalid('Selecione ao menos um dado comum.');
  const changes:Partial<TitleData>={};
  if(Object.hasOwn(patch,'description'))changes.description=text(patch.description,255);
  if(Object.hasOwn(patch,'notes'))changes.notes=text(patch.notes,6000,true);
  if(Object.hasOwn(patch,'categoryId'))changes.categoryId=optionalId(patch.categoryId);
  if(Object.hasOwn(patch,'accountId'))changes.accountId=optionalId(patch.accountId);
  const index=anchor.payload.schedule.index,selected=(await titles(company,c)).filter(t=>t.seriesId===seriesId&&t.status==='draft'&&(b.scope==='all'||(t.payload.schedule?.index??-1)>=index));
  const revisions=obj(b.revisions),expectedIds=Object.keys(revisions).sort(),actualIds=selected.map(t=>t.id).sort();
  if(json(expectedIds)!==json(actualIds))throw new HttpError(409,'Rascunhos da série mudaram; recarregue antes de confirmar.');
  for(const t of selected){cas(revisions[t.id],t.revision);if(t.payload.origin)throw new HttpError(409,'Origem canônica exige revisão específica.');await bucketAccess(u,company,t.payload.bucket,'edit',c);const payload={...t.payload,...changes};await validateLinks(u,company,payload,c);await openPeriods(company,[payload.dueDate,payload.competenceDate],c);}
  const result=[];
  for(const t of selected){const payload={...t.payload,...changes},revision=t.revision+1;await c.execute('UPDATE finance_titles SET payload=?,revision=? WHERE id=? AND company_id=?',[json(payload),revision,t.id,company]);await history(c,u,company,'title',t.id,revision,'series_metadata_edit',b.reason,t,{payload,status:'draft',seriesId,anchorId:anchor.id,scope:b.scope,changedFields:Object.keys(changes)});result.push({id:t.id,revision});}
  return {seriesId,updated:result,amountsAndDatesPreserved:true};
 },async c=>{const anchor=await title(obj(req.body).anchorId,company,c);if(anchor.seriesId!==seriesId)throw new HttpError(404,'Série fora da empresa.');await bucketAccess(u,company,anchor.payload.bucket,'edit',c);}));
});

router.get('/exports/titles',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'export');const f=summaryFilter(req),format=String(req.query.format??'xlsx');if(!['xlsx','csv','json'].includes(format))invalid('Formato inválido.');const data=await consistentRead(u,company,async c=>{await access(u,company,'export',c);const allowed=new Set<string>();for(const b of Object.keys(buckets))if(await checkAccess(u,'scope-company:'+company,'finance',b+'.read',c))allowed.add(b);return (await titles(company,c)).filter(t=>allowed.has(t.payload.bucket)&&t.payload.currency===f.currency&&t.payload.competenceDate>=f.from&&t.payload.competenceDate<=f.to&&(!f.accountId||t.payload.accountId===f.accountId));});if(data.length>10000)invalid('Selecione período menor para exportar até10mil títulos.');const table=[Array.from(importColumns),...data.map(t=>{const p=t.payload;return importColumns.map(k=>k==='externalId'?t.id:String(p[k as keyof TitleData]??''));})];await readAudit(u,company,'titles.export.'+format);if(format==='xlsx')res.type('application/vnd.openxmlformats-officedocument.spreadsheetml.sheet').attachment('titulos-financeiros.xlsx').send(exportXlsx(table));else if(format==='csv')res.type('text/csv;charset=utf-8').attachment('titulos-financeiros.csv').send('\uFEFF'+table.map(r=>r.map(csvCell).join(';')).join('\r\n'));else res.attachment('titulos-financeiros.json').json({companyId:company,filter:f,titles:data,emittedAt:new Date().toISOString(),financialStatePreservedInJsonOnly:true});});

function scenarioData(value:unknown):ScenarioData{const d=obj(value);fields(d,['currency','asOf','horizon','assumptions','adjustments']);const asOf=day(d.asOf),horizon=Number(d.horizon);if(!Number.isSafeInteger(horizon)||horizon<1||horizon>730||!Array.isArray(d.adjustments)||d.adjustments.length>120)invalid('Horizonte/ajustes inválidos.');const end=new Date(asOf+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+horizon);return {currency:currency(d.currency),asOf,horizon,assumptions:text(d.assumptions,6000),adjustments:d.adjustments.map(v=>{const a=obj(v);fields(a,['date','direction','amount','description']);const date=day(a.date),direction=text(a.direction,10),value=decimal(a.amount);if(!['income','expense'].includes(direction)||cents(value)<=0n||date<asOf||date>end.toISOString().slice(0,10))invalid('Ajuste deve ter valor positivo, direção e data dentro do horizonte.');return {date,direction:direction as 'income'|'expense',amount:value,description:text(a.description,255)};})};}
router.get('/scenarios',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company,'balances');await allBuckets(u,company);const data=await consistentRead(u,company,async c=>{await access(u,company,'balances',c);await allBuckets(u,company,c);const list=await rows<{id:string;name:string;payload:unknown;revision:number}>('SELECT id,name,payload,revision FROM finance_scenarios WHERE company_id=? ORDER BY name,id',[company],c),aa=await accounts(company,c),tt=await titles(company,c),ss=await settlements(company,c),mm=await movements(company,c),cc=await categories(company,c);return list.map(s=>{const d=decode(s.payload) as ScenarioData,base=financeSummary(aa,tt,ss,mm,cc,{...d,from:d.asOf,to:d.asOf});return {...s,payload:d,projection:projectScenario(base,d),baseIsLive:true,calculatedAt:new Date().toISOString()};});});await readAudit(u,company,'scenario.read');res.json(data);});
for(const editing of [false,true])router[editing?'put':'post']('/scenarios'+(editing?'/:id':''),async(req,res)=>{const company=co(req),u=res.locals.user;res.status(editing?200:201).json(await write(req,u,company,'edit',async(c,b)=>{fields(b,['companyId','requestId','reason','name','data',...(editing?['revision']:[])]);const d=scenarioData(b.data),name=text(b.name,160),id=editing?uuid(req.params.id):randomUUID();let revision=1,before:unknown=null;if(editing){const [old]=await rows<{revision:number;payload:unknown;name:string}>('SELECT revision,payload,name FROM finance_scenarios WHERE id=? AND company_id=?',[id,company],c);if(!old)throw new HttpError(404,'Cenário fora da empresa.');cas(b.revision,old.revision);before=old;revision=old.revision+1;await c.execute('UPDATE finance_scenarios SET name=?,payload=?,revision=? WHERE id=? AND company_id=?',[name,json(d),revision,id,company]);}else await c.execute('INSERT INTO finance_scenarios(id,company_id,name,payload) VALUES (?,?,?,?)',[id,company,name,json(d)]);await history(c,u,company,'scenario',id,revision,editing?'edit':'create',b.reason,before,{name,payload:d});return {id,revision,createsFinancialFacts:false};},async c=>{await access(u,company,'balances',c);await allBuckets(u,company,c);}));});


for(const collection of ['accounts','categories','dimensions'] as const)router.put('/'+collection+'/:id',async(req,res)=>{const company=co(req),u=res.locals.user;res.json(await write(req,u,company,'governance',async(c,b)=>{fields(b,['companyId','requestId','revision','name','active','reason']);if(typeof b.active!=='boolean')invalid('Estado ativo deve ser booleano.');const id=uuid(req.params.id),table='finance_'+collection,[old]=await rows<{id:string;name:string;revision:number;active:boolean}>('SELECT * FROM '+table+' WHERE id=? AND company_id=?',[id,company],c);if(!old)throw new HttpError(404,'Cadastro fora da empresa.');cas(b.revision,old.revision);const name=text(b.name,160),revision=old.revision+1;await c.execute('UPDATE '+table+' SET name=?,active=?,revision=? WHERE id=? AND company_id=?',[name,b.active,revision,id,company]);await history(c,u,company,collection,id,revision,'configure',b.reason,old,{...old,name,active:b.active,revision,financialNatureAndOpeningUnchanged:true});return {id,revision,name,active:b.active};},c=>allBuckets(u,company,c)));});
router.get('/preferences',async(req,res)=>{const company=co(req),u=res.locals.user;await access(u,company);const [p]=await rows<{revision:number;payload:unknown}>('SELECT revision,payload FROM finance_preferences WHERE user_id=? AND company_id=?',[u.id,company]);res.json(p?{revision:p.revision,data:decode(p.payload)}:{revision:0,data:{currency:'BRL',horizon:90,dueAlertDays:7}});});
router.put('/preferences',async(req,res)=>{const company=co(req),u=res.locals.user;res.json(await write(req,u,company,'read',async(c,b)=>{fields(b,['companyId','requestId','revision','data','reason']);const d=obj(b.data);fields(d,['currency','horizon','dueAlertDays']);const cur=currency(d.currency),horizon=Number(d.horizon),dueAlertDays=Number(d.dueAlertDays);if(!['BRL','MZN'].includes(cur)||!Number.isSafeInteger(horizon)||horizon<1||horizon>730||!Number.isSafeInteger(dueAlertDays)||dueAlertDays<0||dueAlertDays>90)invalid('Preferências inválidas.');const [old]=await rows<{revision:number;payload:unknown}>('SELECT revision,payload FROM finance_preferences WHERE user_id=? AND company_id=?',[u.id,company],c);cas(b.revision,old?.revision??0);const revision=(old?.revision??0)+1,data={currency:cur,horizon,dueAlertDays};await c.execute('INSERT INTO finance_preferences(user_id,company_id,revision,payload) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE revision=VALUES(revision),payload=VALUES(payload)',[u.id,company,revision,json(data)]);await history(c,u,company,'preference',u.id,revision,'save',b.reason,old??null,data);return {revision,data};}));});
router.get('/alerts',async(req,res)=>{const company=co(req),u=res.locals.user;const result=await consistentRead(u,company,async c=>{const [pref]=await rows<{payload:unknown}>('SELECT payload FROM finance_preferences WHERE user_id=? AND company_id=?',[u.id,company],c),days=pref?decode(pref.payload).dueAlertDays:7,asOf=today(),end=new Date(asOf+'T00:00:00Z');end.setUTCDate(end.getUTCDate()+days);const ss=(await settlements(company,c)).filter(s=>s.date<=asOf),allowed=new Set<string>();for(const b of Object.keys(buckets))if(await checkAccess(u,'scope-company:'+company,'finance',b+'.read',c))allowed.add(b);return {asOf,dueAlertDays:days,externalNotifications:false,titles:(await titles(company,c)).filter(t=>allowed.has(t.payload.bucket)&&t.status==='approved'&&t.payload.dueDate<=end.toISOString().slice(0,10)&&cents(pending(t,ss))>0n).map(t=>({id:t.id,description:t.payload.description,currency:t.payload.currency,dueDate:t.payload.dueDate,pending:pending(t,ss),overdue:t.payload.dueDate<asOf}))};});await readAudit(u,company,'alerts.read');res.json(result);});
